segments.en:
padding: 50px 40px 80px 40px;

text-align: justify;

/* ── TITLES ── */

.book-title {

text-align: center;

font-size: 2em;

font-weight: bold;

color: #4a2000;

letter-spacing: 1px;

margin-bottom: 6px;

.section-title {

text-align: center;

font-size: 1.5em;

.halacha-range { font-size: 0.9em; color: var(--muted); letter-spacing: 1px; }

.preamble-box { background: var(--section-bg); border-left: 4px solid var(--accent); padding: 18px 22px; margin: 0 0 34px 0; font-size: 0.95em; color: #3a2000; line-height: 1.75; }

.preamble-box .source-ref { font-size: 0.85em; color: var(--muted); font-style: italic; margin-top: 8px; display: block; }

.translator-summary p { text-indent: 0; margin-bottom: 10px; font-size: 0.95em; }

.flowchart { margin: 30px auto; text-align: center; }

.flow-box { display: inline-block; border: 2px solid var(--accent); border-radius: 8px; padding: 10px 16px; margin: 6px; background: #fff; font-size: 15px; font-weight: 600; color: var(--accent); max-width: 280px; vertical-align: top; }

.flow-arrow { display: block; text-align: center; font-size: 22px; color: var(--gold); margin: 2px 0; }
